theorem f_inequality : (∀ (f : ℚ → ℝ) (hpos : ∀ x : ℚ, 0 < x → 0 < f x) (a b : ℚ) (ha : 0 < a) (hb : 0 < b), f (a * b) = f a + f b) → (∀ (p : ℕ) (hp : Nat.Prime p), f (p : ℚ) = (p : ℝ)) → 
    (let candidates : Set ℚ := {(17/32 : ℚ), 11/16, 7/9, 7/6, 25/11}; 
        x ∈ candidates → f x < 0) ∧ f (25/11 : ℚ) < 0 := sorry

theorem count_solutions_eq_two : 
    let f : ℝ → ℝ := fun x => Real.sin ((π / 2) * Real.cos x)
    let g : ℝ → ℝ := fun x => Real.cos ((π / 2) * Real.sin x)
    in Finset.card (Finset.filter (fun x => f x = g x) (Set.Icc (0 : ℝ) π).toFinset) = 2 := sorry

theorem count_solutions : 
    let x : ℝ := x; 
    hx_nonneg : 0 ≤ x := by
      intro hx_nonneg;
    hx_le : x ≤ 2 * π := by
      intro hx_le;
    f : ℝ → ℝ := λ x => Real.tan (2 * x);
    g : ℝ → ℝ := λ x => Real.cos (x / 2);
    hf : ∀ x, f x = Real.tan (2 * x) := by
      intro x; rfl;
    hg : ∀ x, g x = Real.cos (x / 2) := by
      intro x; rfl;
    hcond1 : ∀ (x : ℝ) (k : ℤ), 2 * x ≠ π / 2 + (k : ℝ) * π := by
      intro x k; exact ?_;
    hcond2 : ∀ (x : ℝ) (k : ℤ), 2 * x ≠ -π / 2 + (k : ℝ) * π := by
      intro x k; exact ?_;
    in
    Finset.card {x | x ∈ Set.Icc (0 : ℝ) (2 * π) ∧ f x = g x} = 5 := sorry
